Method.Source:
    /// <summary>
    /// For charge through pending vendor invoice, if settlement discount exclude charges parameter is Yes
    /// recalculate the settlement discount exluding any charges for the totals screen
    /// The value will also flow into VENDINVOICEJOUR.CASHDISC
    /// </summary>
    /// <returns>Settlement discount amount</returns>
    DiscAmount cashDisc()
    {
        totalCashDisc = next cashDisc();

        if (!parmTable.ReCalculate)
        {
            totalCashDisc = parmTable.CashDisc;
            return totalCashDisc;
        }

        if (parmTable.isNonPO())
        {
            METVendParameters metVendParameters = METVendParameters::find();
            VendInvoiceInfoTable vendInvoiceInfoTable = parmTable;

            if (metVendParameters.SettlementDiscChargeExclusion
            && (vendInvoiceInfoTable.METChargeThrough || vendInvoiceInfoTable.METCrossDock))
            {
                totalCashDisc = VendParameters::cashDiscAmount(
                        parmTable.CashDiscCode,
                        this.purchCurrency(),
                        totalAmount - this.purchMarkup(), // exclude charges from the amount
                        totalAmount - this.purchMarkup() - this.purchTaxTotal(), // exclude charges from the amount
                        parmTable.CashDiscPercent);
            }
        }
        return totalCashDisc;
    }
